{
    "anonymous_name": "fn_63",
    "readable_name": "determine_shape_based_on_material_count",
    "description": "Determines the shape of an object based on the material count of a list of objects. If the material count is greater than 7, it checks the material of the first object in the list. If the material is rubber, it returns a cylinder shape; otherwise, it returns a sphere shape."
}

